using System; using System.Data.SqlClient; namespace PlacementDashboard.Admin { public partial class AddStudent : System.Web.UI.Page { protected void Save_Click(object sender,EventArgs e) { decimal p; if(!Page.IsValid || !decimal.TryParse(Package.Text,out p)) { Message.Text="Enter a valid package."; return; } PlacementDashboard.DBConnection.Execute("INSERT INTO Students(StudentName,Department,Company,Package,PlacementStatus) VALUES(@n,@d,@c,@p,@s)",new SqlParameter("@n",StudentName.Text),new SqlParameter("@d",Department.Text),new SqlParameter("@c",(object)Company.Text??DBNull.Value),new SqlParameter("@p",p),new SqlParameter("@s",Status.SelectedValue)); Response.Redirect("ViewStudents.aspx"); } } }
